message.content:
FreeLang Nexus 프로젝트 `/data/data/com.termux/files/home/projects/freelang-nexus`에서 Formatter를 구현해주세요.

## 목표
AST 기반 코드 포매터 + `nexus format` CLI 명령어

## 먼저 확인할 파일
- `src/nexus/parser/ast.ts` — AST 노드 타입 전체 확인 (필수)
- `src/nexus/index.ts` — CLI 구조 확인 (format 명령 추가 위치)

## 구현 내용

### 1. `src/nexus/formatter/nexus-formatter.ts` 신규 생성 (~280줄)

AST → 포맷된 소스 코드 재생성:
- 들여쓰기 2스페이스
- 중괄호 같은 줄 `{`
- 이항 연산자 양쪽 공백 (`a + b`, `x == y`)
- 함수 인자 콤마 뒤 공백 (`fn add(a: i64, b: i64)`)
- 지원 안 되는 노드는 `// [unsupported: NodeType]` 주석으로 출력

```typescript
import * as AST from '../parser/ast';

export class NexusFormatter {
  private indent = 0;
  private lines: string[] = [];

  format(ast: AST.Program): string {
    this.indent = 0;
    this.lines = [];
    for (const node of ast.body) {
      this.emitNode(node as any);
      this.lines.push('');  // 빈 줄 구분
    }
    return this.lines.join('\n').trimEnd() + '\n';
  }

  private push(line: string): void {
    this.lines.push('  '.repeat(this.indent) + line);
  }

  private emitNode(node: any): void {
    switch (node.type) {
      case 'VFunction': this.emitVFunction(node); break;
      case 'StructDef': this.emitStructDef(node); break;
      case 'ExternCall': this.emitExternCall(node); break;
      case 'LangBlock': this.emitLangBlock(node); break;
      default: this.emitStatement(node); break;
    }
  }

  private emitVFunction(fn: AST.VFunction): void {
    const params = fn.params.map(p =>
      p.typeAnnotation ? `${p.name}: ${p.typeAnnotation}` : p.name
    ).join(', ');
    const ret = fn.returnType ? ` -> ${fn.returnType}` : '';
    this.push(`fn ${fn.name}(${params})${ret} {`);
    this.indent++;
    for (const stmt of fn.body) this.emitStatement(stmt as any);
    this.indent--;
    this.push('}');
  }

  private emitStatement(stmt: any): void {
    switch (stmt.type) {
      case 'Return':
        this.push(`return ${stmt.value ? this.emitExpr(stmt.value) : ''}`);
        break;
      case 'Assign':
        if (stmt.declared) {
          this.push(`let ${stmt.name} = ${this.emitExpr(stmt.value)}`);
        } else {
          this.push(`${stmt.name} = ${this.emitExpr(stmt.value)}`);
        }
        break;
      case 'IfStatement':
        this.emitIf(stmt);
        break;
      case 'WhileStatement':
        this.push(`while ${this.emitExpr(stmt.condition)} {`);
        this.indent++;
        for (const s of stmt.body) this.emitStatement(s);
        this.indent--;
        this.push('}');
        break;
      case 'ForStatement':
        this.push(`for ${stmt.variable} in range(${this.emitExpr(stmt.start)}, ${this.emitExpr(stmt.end)}) {`);
        this.indent++;
        for (const s of stmt.body) this.emitStatement(s);
        this.indent--;
        this.push('}');
        break;
      case 'ExprStatement':
        this.push(this.emitExpr(stmt.expression));
        break;
      case 'Break': this.push('break'); break;
      case 'Continue': this.push('continue'); break;
      default:
        this.push(`// [unsupported: ${stmt.type}]`);
    }
  }

  private emitIf(stmt: any): void {
    this.push(`if ${this.emitExpr(stmt.condition)} {`);
    this.indent++;
    for (const s of stmt.thenBody) this.emitStatement(s);
    this.indent--;
    if (stmt.elseBody && stmt.elseBody.length > 0) {
      // else if 체인
      if (stmt.elseBody.length === 1 && stmt.elseBody[0].type === 'IfStatement') {
        this.push('} else ');
        this.emitIf(stmt.elseBody[0]);
        return;
      }
      this.push('} else {');
      this.indent++;
      for (const s of stmt.elseBody) this.emitStatement(s);
      this.indent--;
    }
    this.push('}');
  }

  private emitExpr(expr: any): string {
    if (!expr) return '';
    switch (expr.type) {
      case 'Number': return String(expr.value);
      case 'String': return expr.value;  // 따옴표 포함
      case 'Boolean': return String(expr.value);
      case 'Identifier': return expr.name;
      case 'BinaryExpr':
        return `${this.emitExpr(expr.left)} ${expr.op} ${this.emitExpr(expr.right)}`;
      case 'UnaryExpr':
        return `${expr.op}${this.emitExpr(expr.operand)}`;
      case 'Call':
        if (expr.callee?.type === 'MemberAccess') {
          return `${this.emitExpr(expr.callee.object)}.${expr.callee.property}(${expr.args.map((a: any) => this.emitExpr(a)).join(', ')})`;
        }
        return `${this.emitExpr(expr.callee)}(${expr.args.map((a: any) => this.emitExpr(a)).join(', ')})`;
      case 'MemberAccess':
        return `${this.emitExpr(expr.object)}.${expr.property}`;
      case 'IndexAccess':
        return `${this.emitExpr(expr.object)}[${this.emitExpr(expr.index)}]`;
      case 'StructLiteral':
        const fields = expr.fields.map((f: any) => `${f.name}: ${this.emitExpr(f.value)}`).join(', ');
        return `${expr.name} { ${fields} }`;
      default:
        return `/* [unsupported expr: ${expr.type}] */`;
    }
  }

  private emitStructDef(def: any): void {
    const fields = def.fields.map((f: any) => `${f.name}: ${f.typeAnnotation}`).join(', ');
    this.push(`struct ${def.name} { ${fields} }`);
  }

  private emitExternCall(node: any): void {
    const alias = node.alias ? ` as ${node.alias}` : '';
    const version = node.version ? ` ${node.version}` : '';
    this.push(`@call ${node.lang}:${node.package}${version}${alias}`);
  }

  private emitLangBlock(node: any): void {
    this.push(`@lang("${node.lang}")`);
    if (node.artifact) this.push(`@artifact("${node.artifact}")`);
    if (node.compileCmd) this.push(`@compile("${node.compileCmd}")`);
    this.push('---');
    for (const line of node.sourceCode.split('\n')) {
      this.push(line);
    }
    this.push('---');
  }
}
```

### 2. `src/nexus/index.ts` 수정 — `format` 서브커맨드 추가

기존 CLI 구조에 맞게 추가:
```typescript
} else if (cmd === 'format') {
  const writeMode = args.includes('--write') || args.includes('-w');
  if (!file) {
    console.error('사용법: nexus format <file> [--write]');
    process.exit(1);
  }
  const source = fs.readFileSync(file, 'utf-8');
  const tokens = new NexusLexer(source).tokenize();
  const ast = new NexusParser(tokens, source).parse();
  const { NexusFormatter } = await import('./formatter/nexus-formatter');
  const formatter = new NexusFormatter();
  const formatted = formatter.format(ast);
  if (writeMode) {
    fs.writeFileSync(file, formatted, 'utf-8');
    console.log(`✅ 포맷 완료: ${file}`);
  } else {
    process.stdout.write(formatted);
  }
}
```

`printUsage()`에도 format 명령 추가.

