     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  typeAnnotation?: string; // let x: i64[] = ... 형식 타입 힌트
    67→  value: Expression;
    68→}
    69→
    70→/**
    71→ * 표현식 문장
    72→ */
    73→export interface ExprStatement extends ASTNode {
    74→  type: 'ExprStatement';
    75→  expression: Expression;
    76→}
    77→
    78→/**
    79→ * If 문장
    80→ */
    81→export interface IfStatement extends ASTNode {
    82→  type: 'IfStatement';
    83→  condition: Expression;
    84→  thenBranch: Statement[];
    85→  elseBranch?: Statement[];
    86→}
    87→
    88→/**
    89→ * While 루프
    90→ */
    91→export interface WhileStatement extends ASTNode {
    92→  type: 'WhileStatement';
    93→  condition: Expression;
    94→  body: Statement[];
    95→}
    96→
    97→/**
    98→ * Break 문장
    99→ */
   100→export interface BreakStatement extends ASTNode {
   101→  type: 'Break';
   102→}
   103→
   104→/**
   105→ * Continue 문장
   106→ */
   107→export interface ContinueStatement extends ASTNode {
   108→  type: 'Continue';
   109→}
   110→
   111→/**
   112→ * For-In 루프
   113→ * for i in range(10) { body }
   114→ * for item in arr { body }
   115→ */
   116→export interface ForStatement extends ASTNode {
   117→  type: 'ForStatement';
   118→  variable: string;     // 루프 변수명
   119→  iterable: Expression; // range(10) CallExpr 또는 arr Identifier
   120→  body: Statement[];
   121→}
   122→
   123→/**
   124→ * match/case 패턴 매칭 arm
   125→ * case 1 => { ... }  또는  case _ => { ... }
   126→ */
   127→export interface MatchArm {
   128→  pattern: Expression | null;  // null = wildcard (_)
   129→  body: Statement[];
   130→  line: number;
   131→  column: number;
   132→}
   133→
   134→/**
   135→ * match 문장
   136→ * match x { case 1 => { ... } case _ => { ... } }
   137→ */
   138→export interface MatchStatement extends ASTNode {
   139→  type: 'MatchStatement';
   140→  subject: Expression;
   141→  arms: MatchArm[];
   142→}
   143→
   144→/**
   145→ * 문장 타입
   146→ */
   147→export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement | WhileStatement | ForStatement | BreakStatement | ContinueStatement | MatchStatement;
   148→
   149→/**
   150→ * 숫자 리터럴
   151→ */
   152→export interface NumberLiteral extends ASTNode {
   153→  type: 'Number';
   154→  value: number | string; // 16진수, 이진수 표현 가능
   155→}
   156→
   157→/**
   158→ * 문자열 리터럴
   159→ */
   160→export interface StringLiteral extends ASTNode {
   161→  type: 'String';
   162→  value: string;
   163→}
   164→
   165→/**
   166→ * 식별자 (변수명, 함수명 등)
   167→ */
   168→export interface Identifier extends ASTNode {
   169→  type: 'Identifier';
   170→  name: string;
   171→}
   172→
   173→/**
   174→ * 이항 연산식
   175→ * 예: x + y, a * b
   176→ */
   177→export interface BinaryExpr extends ASTNode {
   178→  type: 'BinaryExpr';
   179→  left: Expression;
   180→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   181→  right: Expression;
   182→}
   183→
   184→/**
   185→ * 함수 호출 표현식
   186→ * 예: foo(), Module::func()
   187→ */
   188→export interface CallExpr extends ASTNode {
   189→  type: 'Call';
   190→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   191→  args: Expression[];
   192→}
   193→
   194→/**
   195→ * 배열 리터럴
   196→ * 예: [1, 2, 3], []
   197→ */
   198→export interface ArrayLiteral extends ASTNode {
   199→  type: 'Array';
   200→  elements: Expression[];
   201→}
   202→
   203→/**
   204→ * 배열 접근
   205→ * 예: arr[0], items[i]
   206→ */
   207→export interface ArrayAccess extends ASTNode {
   208→  type: 'ArrayAccess';
   209→  object: Expression;
   210→  index: Expression;
   211→}
   212→
   213→/**
   214→ * 멤버 접근
   215→ * 예: arr.length, obj.property
   216→ */
   217→export interface MemberAccess extends ASTNode {
   218→  type: 'MemberAccess';
   219→  object: Expression;
   220→  property: string;
   221→}
   222→
   223→/**
   224→ * 구조체 필드 정의
   225→ */
   226→export interface StructField {
   227→  name: string;
   228→  typeAnnotation: string;
   229→  line: number;
   230→  column: number;
   231→}
   232→
   233→/**
   234→ * 구조체 정의
   235→ * 예: struct Person { name: string, age: i64 }
   236→ */
   237→export interface StructDef extends ASTNode {
   238→  type: 'StructDef';
   239→  name: string;
   240→  fields: StructField[];
   241→  mode: 'v';
   242→}
   243→
   244→/**
   245→ * 구조체 리터럴
   246→ * 예: Person { name: "Alice", age: 30 }
   247→ */
   248→export interface StructLiteral extends ASTNode {
   249→  type: 'StructLiteral';
   250→  name: string;
   251→  fields: { [key: string]: Expression };
   252→}
   253→
   254→/**
   255→ * 표현식 타입
   256→ */
   257→export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr | ArrayLiteral | ArrayAccess | MemberAccess | StructLiteral;
   258→
   259→/**
   260→ * @call 지시문 - 외부 언어 라이브러리 호출 (버스 터미널)
   261→ * @call python:numpy 1.24
   262→ * @call rust:rand 0.8
   263→ * @call go:github.com/gin-gonic/gin
   264→ */
   265→export interface ExternCall extends ASTNode {
   266→  type: 'ExternCall';
   267→  lang: 'python' | 'rust' | 'go' | 'julia' | 'js' | 'c' | 'cpp' | 'ruby' | 'node' | 'zig';
   268→  package: string;   // 패키지명 (numpy, rand, github.com/... 등)
   269→  version?: string;  // 선택적 버전 (1.24, 0.8 등)
   270→  alias?: string;    // as alias (선택)
   271→}
   272→
   273→/**
   274→ * 다중언어 코드 블록
   275→ * @lang("rust")
   276→ * @artifact("librustcore.so")
   277→ * @compile("rustc --crate-type cdylib ...")
   278→ * ---
   279→ * 실제 소스 코드
   280→ * ---
   281→ */
   282→export interface LangBlock extends ASTNode {
   283→  type: 'LangBlock';
   284→  lang: string;          // "rust", "zig", "julia", "go", "c", "cpp", "python"
   285→  artifact?: string;     // 생성될 아티팩트 파일명 (예: librustcore.so)
   286→  compileCmd?: string;   // 컴파일 명령어 (예: rustc --crate-type cdylib ...)
   287→  sourceCode: string;    // --- ... --- 사이의 실제 원본 소스 코드
   288→  cgo?: boolean;         // @cgo 지시문 여부 (Go cgo 직접 호출)
   289→  dependsOn?: string[];  // @depends_on 의존성 리스트
   290→}
   291→
   292→/**
   293→ * 공유 메모리 디렉티브
   294→ * @shared_mem("result_buf", size=64, type="i64")
   295→ * POSIX shm_open() + mmap()으로 명명된 공유 메모리 생성
   296→ */
   297→export interface SharedMemDirective extends ASTNode {
   298→  type: 'SharedMemDirective';
   299→  name: string;      // shm 이름 (예: "result_buf")
   300→  size: number;      // 원소 수 (예: 64)
   301→  dataType: string;  // 데이터 타입 (예: "i64", "f64")
   302→}
   303→
   304→/**
   305→ * 프로그램 (최상위 노드)
   306→ */
   307→export interface Program {
   308→  type: 'Program';
   309→  body: Array<VFunction | PyFunction | StructDef | Statement | ExternCall | LangBlock | SharedMemDirective>;
   310→}
