/**
 * FreeLang Nexus - AST 기반 코드 포매터
 * AST → 포맷된 소스 코드 재생성
 *
 * 포맷 규칙:
 *   - 들여쓰기: 2스페이스
 *   - 중괄호: 같은 줄 `{`
 *   - 이항 연산자 양쪽 공백: `a + b`, `x == y`
 *   - 함수 인자 콤마 뒤 공백: `fn add(a: i64, b: i64)`
 *   - 미지원 노드: `// [unsupported: NodeType]` 주석 출력
 */

import * as AST from '../parser/ast';

export class NexusFormatter {
  private indent = 0;
  private lines: string[] = [];

  /**
   * AST → 포맷된 소스 코드 문자열 반환
   */
  format(ast: AST.Program): string {
    this.indent = 0;
    this.lines = [];

    for (const node of ast.body) {
      this.emitTopLevel(node as any);
      this.lines.push('');  // 최상위 노드 사이 빈 줄
    }

    return this.lines.join('\n').trimEnd() + '\n';
  }

  // ─── 내부 헬퍼 ───────────────────────────────────────────────

  /** 현재 들여쓰기 수준으로 줄 추가 */
  private push(line: string): void {
    if (line === '') {
      this.lines.push('');
    } else {
      this.lines.push('  '.repeat(this.indent) + line);
    }
  }

  // ─── 최상위 노드 ─────────────────────────────────────────────

  private emitTopLevel(node: any): void {
    switch (node.type) {
      case 'VFunction':        this.emitVFunction(node); break;
      case 'PyFunction':       this.emitPyFunction(node); break;
      case 'StructDef':        this.emitStructDef(node); break;
      case 'ExternCall':       this.emitExternCall(node); break;
      case 'LangBlock':        this.emitLangBlock(node); break;
      case 'SharedMemDirective': this.emitSharedMem(node); break;
      default:                 this.emitStatement(node); break;
    }
  }

  // ─── 함수 ────────────────────────────────────────────────────

  private emitVFunction(fn: AST.VFunction): void {
    const params = fn.params
      .map(p => p.typeAnnotation ? `${p.name}: ${p.typeAnnotation}` : p.name)
      .join(', ');
    const ret = fn.returnType ? ` -> ${fn.returnType}` : '';
    this.push(`fn ${fn.name}(${params})${ret} {`);
    this.indent++;
    for (const stmt of fn.body) this.emitStatement(stmt as any);
    this.indent--;
    this.push('}');
  }

  private emitPyFunction(fn: AST.PyFunction): void {
    const params = fn.params
      .map(p => p.typeAnnotation ? `${p.name}: ${p.typeAnnotation}` : p.name)
      .join(', ');
    const ret = fn.returnType ? ` -> ${fn.returnType}` : '';
    this.push(`def ${fn.name}(${params})${ret}:`);
    this.indent++;
    for (const stmt of fn.body) this.emitStatement(stmt as any);
    this.indent--;
  }

  // ─── 문장 ────────────────────────────────────────────────────

  private emitStatement(stmt: any): void {
    switch (stmt.type) {
      case 'Return':
        this.push(`return ${stmt.value ? this.emitExpr(stmt.value) : ''}`);
        break;

      case 'Assign':
        if (stmt.typeAnnotation) {
          this.push(`let ${stmt.name}: ${stmt.typeAnnotation} = ${this.emitExpr(stmt.value)}`);
        } else {
          // let 선언과 재할당 구분: AST에서 declared 필드가 없으므로
          // 컨텍스트 없이는 let과 일반 할당을 구분할 수 없음.
          // 파서가 둘 다 'Assign'으로 생성하므로 let 형태로 출력.
          this.push(`let ${stmt.name} = ${this.emitExpr(stmt.value)}`);
        }
        break;

      case 'IfStatement':
        this.emitIf(stmt);
        break;

      case 'WhileStatement':
        this.push(`while ${this.emitExpr(stmt.condition)} {`);
        this.indent++;
        for (const s of stmt.body) this.emitStatement(s);
        this.indent--;
        this.push('}');
        break;

      case 'ForStatement':
        this.emitFor(stmt);
        break;

      case 'MatchStatement':
        this.emitMatch(stmt);
        break;

      case 'ExprStatement':
        this.push(this.emitExpr(stmt.expression));
        break;

      case 'Break':
        this.push('break');
        break;

      case 'Continue':
        this.push('continue');
        break;

      default:
        this.push(`// [unsupported: ${stmt.type}]`);
    }
  }

  // ─── if / else if / else ──────────────────────────────────────

  private emitIf(stmt: AST.IfStatement): void {
    this.push(`if ${this.emitExpr(stmt.condition)} {`);
    this.indent++;
    for (const s of stmt.thenBranch) this.emitStatement(s as any);
    this.indent--;

    const els = stmt.elseBranch;
    if (els && els.length > 0) {
      // else if 체인: elseBranch에 단일 IfStatement가 있는 경우
      if (els.length === 1 && (els[0] as any).type === 'IfStatement') {
        // '} else if ...' 형태로 출력 — 마지막 줄을 교체
        const lastIdx = this.lines.length - 1;
        const lastLine = this.lines[lastIdx];
        this.lines[lastIdx] = lastLine + ' else ';
        this.emitIfContinuation(els[0] as any);
      } else {
        this.push('} else {');
        this.indent++;
        for (const s of els) this.emitStatement(s as any);
        this.indent--;
        this.push('}');
      }
    } else {
      this.push('}');
    }
  }

  /** else if 체인 계속 출력 — 앞에 이미 '} else '가 붙어 있음 */
  private emitIfContinuation(stmt: AST.IfStatement): void {
    // 현재 마지막 줄에 'if COND {' 를 이어붙임
    const lastIdx = this.lines.length - 1;
    this.lines[lastIdx] = this.lines[lastIdx] + `if ${this.emitExpr(stmt.condition)} {`;

    this.indent++;
    for (const s of stmt.thenBranch) this.emitStatement(s as any);
    this.indent--;

    const els = stmt.elseBranch;
    if (els && els.length > 0) {
      if (els.length === 1 && (els[0] as any).type === 'IfStatement') {
        const idx = this.lines.length - 1;
        this.lines[idx] = this.lines[idx] + ' else ';
        this.emitIfContinuation(els[0] as any);
      } else {
        this.push('} else {');
        this.indent++;
        for (const s of els) this.emitStatement(s as any);
        this.indent--;
        this.push('}');
      }
    } else {
      this.push('}');
    }
  }

  // ─── for ─────────────────────────────────────────────────────

  private emitFor(stmt: AST.ForStatement): void {
    const iter = this.emitExpr(stmt.iterable as any);
    this.push(`for ${stmt.variable} in ${iter} {`);
    this.indent++;
    for (const s of stmt.body) this.emitStatement(s as any);
    this.indent--;
    this.push('}');
  }

  // ─── match ───────────────────────────────────────────────────

  private emitMatch(stmt: AST.MatchStatement): void {
    this.push(`match ${this.emitExpr(stmt.subject)} {`);
    this.indent++;
    for (const arm of stmt.arms) {
      const pat = arm.pattern ? this.emitExpr(arm.pattern as any) : '_';
      this.push(`case ${pat} => {`);
      this.indent++;
      for (const s of arm.body) this.emitStatement(s as any);
      this.indent--;
      this.push('}');
    }
    this.indent--;
    this.push('}');
  }

  // ─── 표현식 ──────────────────────────────────────────────────

  private emitExpr(expr: any): string {
    if (!expr) return '';

    switch (expr.type) {
      case 'Number':
        return String(expr.value);

      case 'String':
        // 따옴표 포함된 문자열 그대로 반환
        return expr.value;

      case 'Identifier':
        return expr.name;

      case 'BinaryExpr':
        return `${this.emitExpr(expr.left)} ${expr.operator} ${this.emitExpr(expr.right)}`;

      case 'Call': {
        const callee = typeof expr.callee === 'string'
          ? expr.callee
          : this.emitExpr(expr.callee);
        const args = expr.args.map((a: any) => this.emitExpr(a)).join(', ');
        return `${callee}(${args})`;
      }

      case 'Array': {
        const elems = expr.elements.map((e: any) => this.emitExpr(e)).join(', ');
        return `[${elems}]`;
      }

      case 'ArrayAccess':
        return `${this.emitExpr(expr.object)}[${this.emitExpr(expr.index)}]`;

      case 'MemberAccess':
        return `${this.emitExpr(expr.object)}.${expr.property}`;

      case 'StructLiteral': {
        const fields = Object.entries(expr.fields as { [key: string]: any })
          .map(([k, v]) => `${k}: ${this.emitExpr(v)}`)
          .join(', ');
        return `${expr.name} { ${fields} }`;
      }

      default:
        return `/* [unsupported expr: ${expr.type}] */`;
    }
  }

  // ─── 최상위 구조 선언 ────────────────────────────────────────

  private emitStructDef(def: AST.StructDef): void {
    const fields = def.fields
      .map(f => `${f.name}: ${f.typeAnnotation}`)
      .join(', ');
    this.push(`struct ${def.name} { ${fields} }`);
  }

  private emitExternCall(node: AST.ExternCall): void {
    const alias = node.alias ? ` as ${node.alias}` : '';
    const version = node.version ? ` ${node.version}` : '';
    this.push(`@call ${node.lang}:${node.package}${version}${alias}`);
  }

  private emitLangBlock(node: AST.LangBlock): void {
    this.push(`@lang("${node.lang}")`);
    if (node.artifact) this.push(`@artifact("${node.artifact}")`);
    if (node.compileCmd) this.push(`@compile("${node.compileCmd}")`);
    if (node.cgo) this.push('@cgo');
    if (node.dependsOn && node.dependsOn.length > 0) {
      for (const dep of node.dependsOn) {
        this.push(`@depends_on("${dep}")`);
      }
    }
    this.push('---');
    const codeLines = node.sourceCode.split('\n');
    for (const line of codeLines) {
      // lang 블록 내부 코드는 들여쓰기 없이 그대로 출력
      this.lines.push(line);
    }
    this.push('---');
  }

  private emitSharedMem(node: AST.SharedMemDirective): void {
    this.push(`@shared_mem("${node.name}", size=${node.size}, type="${node.dataType}")`);
  }
}

