/**
 * FreeLang Nexus - 포매터 테스트
 *
 * FMT-1: fn 정의 포맷 (들여쓰기 2스페이스)
 * FMT-2: if/else 포맷
 * FMT-3: while 루프 포맷
 * FMT-4: struct 포맷
 * FMT-5: 이항 연산자 공백
 * FMT-6: round-trip (포맷 후 재파싱 에러 없음)
 * FMT-7: for 루프 포맷
 * FMT-8: 함수 호출 포맷
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusFormatter } from '../src/nexus/formatter/nexus-formatter';

/** 소스 코드를 파싱하여 AST를 반환하는 헬퍼 */
function parse(source: string) {
  const tokens = new NexusLexer(source).tokenize();
  return new NexusParser(tokens, source).parse();
}

/** 소스 코드를 포맷하여 문자열 반환 */
function fmt(source: string): string {
  const ast = parse(source);
  return new NexusFormatter().format(ast);
}

// ─── FMT-1: fn 정의 포맷 ────────────────────────────────────────────────────

describe('FMT-1: fn 정의 포맷', () => {
  test('단순 fn — 2스페이스 들여쓰기', () => {
    const src = `fn add(a: i64, b: i64) -> i64 { return a + b }`;
    const out = fmt(src);
    expect(out).toContain('fn add(a: i64, b: i64) -> i64 {');
    expect(out).toContain('  return a + b');
    expect(out).toContain('}');
  });

  test('파라미터 없는 fn', () => {
    const src = `fn greet() -> string { return "hello" }`;
    const out = fmt(src);
    expect(out).toContain('fn greet() -> string {');
    expect(out).toContain('  return "hello"');
  });

  test('반환 타입 없는 fn', () => {
    const src = `fn noret() { let x = 1 }`;
    const out = fmt(src);
    expect(out).toContain('fn noret() {');
    expect(out).toContain('  let x = 1');
  });
});

// ─── FMT-2: if/else 포맷 ────────────────────────────────────────────────────

describe('FMT-2: if/else 포맷', () => {
  test('단순 if', () => {
    const src = `fn f() { if x > 0 { return 1 } }`;
    const out = fmt(src);
    expect(out).toContain('  if x > 0 {');
    expect(out).toContain('    return 1');
    expect(out).toContain('  }');
  });

  test('if/else', () => {
    const src = `fn f() { if x > 0 { return 1 } else { return 0 } }`;
    const out = fmt(src);
    expect(out).toContain('  if x > 0 {');
    expect(out).toContain('  } else {');
    expect(out).toContain('    return 0');
  });

  test('else if 체인', () => {
    const src = `fn classify(n: i64) -> i64 {
  if n > 0 { return 1 }
  else if n < 0 { return -1 }
