// ─── FMT-3: while 루프 포맷 ─────────────────────────────────────────────────

describe('FMT-3: while 루프 포맷', () => {
  test('기본 while', () => {
    const src = `fn f() { while i < 10 { let i = i + 1 } }`;
    const out = fmt(src);
    expect(out).toContain('  while i < 10 {');
    expect(out).toContain('    let i = i + 1');
    expect(out).toContain('  }');
  });

  test('break / continue', () => {
    const src = `fn f() { while true { break } }`;
    const out = fmt(src);
    expect(out).toContain('    break');
  });
});

// ─── FMT-4: struct 포맷 ─────────────────────────────────────────────────────

describe('FMT-4: struct 포맷', () => {
  test('struct 필드 출력', () => {
    const src = `struct Point { x: i64, y: i64 }`;
    const out = fmt(src);
    expect(out).toContain('struct Point { x: i64, y: i64 }');
  });
});

// ─── FMT-5: 이항 연산자 공백 ─────────────────────────────────────────────────

describe('FMT-5: 이항 연산자 공백', () => {
  test('덧셈 연산자 공백', () => {
    const src = `fn f() -> i64 { return a + b }`;
    const out = fmt(src);
    expect(out).toContain('a + b');
  });

  test('비교 연산자 공백', () => {
    const src = `fn f() { if x == y { return 1 } }`;
    const out = fmt(src);
    expect(out).toContain('x == y');
  });

  test('복합 이항 표현식', () => {
    const src = `fn f() -> i64 { return a * b + c }`;
    const out = fmt(src);
    expect(out).toContain('a * b + c');
  });
});

// ─── FMT-6: round-trip ──────────────────────────────────────────────────────

describe('FMT-6: round-trip (포맷 후 재파싱)', () => {
  test('fn 정의 round-trip', () => {
    const src = `fn add(a: i64, b: i64) -> i64 { return a + b }`;
    const out = fmt(src);
    // 재파싱 시 에러 없어야 함
    expect(() => parse(out)).not.toThrow();
  });

  test('if/else round-trip', () => {
    const src = `fn abs(n: i64) -> i64 { if n < 0 { return -1 } else { return n } }`;
    const out = fmt(src);
    expect(() => parse(out)).not.toThrow();
  });

  test('struct round-trip', () => {
    const src = `struct Rect { w: i64, h: i64 }`;
    const out = fmt(src);
    expect(() => parse(out)).not.toThrow();
  });
});

// ─── FMT-7: for 루프 포맷 ───────────────────────────────────────────────────

describe('FMT-7: for 루프 포맷', () => {
  test('for in range', () => {
    const src = `fn f() { for i in range(10) { let x = i } }`;
    const out = fmt(src);
    expect(out).toContain('  for i in range(10) {');
    expect(out).toContain('    let x = i');
    expect(out).toContain('  }');
  });

  test('for in 배열', () => {
    const src = `fn f() { for item in arr { let x = item } }`;
    const out = fmt(src);
    expect(out).toContain('  for item in arr {');
  });
});

// ─── FMT-8: 함수 호출 포맷 ──────────────────────────────────────────────────

describe('FMT-8: 함수 호출 포맷', () => {
  test('단순 함수 호출', () => {
    const src = `fn f() { println("hello") }`;
    const out = fmt(src);
    expect(out).toContain('  println("hello")');
  });

  test('인자 여러 개 — 콤마 뒤 공백', () => {
    const src = `fn f() { add(a, b, c) }`;
    const out = fmt(src);
    expect(out).toContain('add(a, b, c)');
  });

  test('멤버 메서드 호출', () => {
    const src = `fn f() { arr.push(1) }`;
    const out = fmt(src);
    expect(out).toContain('arr.push(1)');
  });
});

