private emitElseIf(stmt: AST.IfStatement): void {
  this.push(`} else if ${this.emitExpr(stmt.condition)} {`);
  this.indent++;
  for (const s of stmt.thenBranch) this.emitStatement(s as any);
  this.indent--;

